const r=await Promise.allSettled([
tools.exec_command({workdir:w,cmd:review,max_output_tokens:3200,yield_time_ms:1000}),
tools.exec_command({workdir:w,cmd:p+String.raw`$checkpoint = '01M87VGDR3ERJ9W4D09DF5WMCB'
$ref = 'refs/entire/checkpoints/CB/01M87VGDR3ERJ9W4D09DF5WMCB'
$checkpointObject = git rev-parse $ref
"Object=$checkpointObject"
$files = @(git ls-tree -r --name-only $ref)
$files
$details = entire checkpoint explain --checkpoint $checkpoint --json --no-pager | ConvertFrom-Json
$list = entire checkpoint list --json | ConvertFrom-Json
"List root keys: $($list.PSObject.Properties.Name -join ',')"
"Detail root keys: $($details.PSObject.Properties.Name -join ',')"
foreach ($file in $files) {
    $blob = (git show "$($ref):$file") -join [char]10
    $workspaces = [regex]::Matches($blob, '(?i)\blcv-workspace\b').Count
    $profileReferences = [regex]::Matches($blob, '(?i)(?:[A-Z]:[/\\]+Users[/\\]+lcvle)\b').Count
    $keyMarkers = [regex]::Matches($blob, '-----BEGIN [A-Z ]*PRIVATE KEY-----|(?:github_pat_|gh[pousr]_|xox[baprs]-|sk-proj-)[A-Za-z0-9_-]{18,}').Count
    $otherInstruction = [regex]::Matches($blob, 'Operator Master Directive|Apple Account|X-Goog-User-Project|LCV-[0-9]{2,}|audit identifier|support ticket number').Count
    $emails = @([regex]::Matches($blob, '(?i)\b[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}\b').Value | Where-Object { $_ -notmatch '(?i)(@example\.com|@users\.noreply\.github\.com|@noreply\.github\.com|@github\.com)$' } | Select-Object -Unique).Count
    [pscustomobject]@{File=$file; Chars=$blob.Length; ProfilePaths=$profileReferences; Workspaces=$workspaces; InstructionMatches=$otherInstruction; KeyMarkers=$keyMarkers; Emails=$emails} | ConvertTo-Json -Compress
}`,max_output_tokens:10000})
